 static void require(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 static void ready(ServerPlayer p,double x,double z){p.stopUsingItem();p.removeAllEffects();p.getInventory().clearContent();p.snapTo(x,280,z,0,0);p.setNoGravity(true);var m=Utils.getPlayerMahou(p);m.setMaxMana(100000);m.setStoredMana(100000);m.setGeas(new HashSet<>());m.setDamageExchangeUses(0);}
 static ItemStack scroll(String id){return new ItemStack(ModItems.REGISTERED.get("scroll_"+id));}
 static void cast(ServerPlayer p,ItemStack stack){((SpellScroll)stack.getItem()).releaseUsing(stack,p.level(),p,71999);}
 static <T extends Mob>T mob(ServerPlayer p,EntityType<T> type,double x,double y,double z){var e=type.create(p.level(),EntitySpawnReason.COMMAND);e.snapTo(x,y,z,0,0);e.setNoAi(true);require(p.level().addFreshEntity(e),"Native fixture entity insertion");return e;}
 static void recipe(ServerPlayer p,String id,String... powders){var world=p.level();var pos=new BlockPos(530,285,530);world.setBlockAndUpdate(pos,ModBlocks.mahoujin.get().defaultBlockState());((stepsword.mahoutsukai.tile.MahoujinTileEntity)world.getBlockEntity(pos)).setCloth(true);for(String powder:powders){var stack=new ItemStack(ModItems.REGISTERED.get("powdered_"+powder));p.setItemInHand(InteractionHand.MAIN_HAND,stack);world.getBlockState(pos).useItemOn(stack,world,p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false));require(stack.isEmpty(),"Catalyst consumed "+id);}require(net.minecraft.core.registries.BuiltInRegistries.BLOCK.getKey(world.getBlockState(pos).getBlock()).getPath().equals("mahoujin_"+id),"Original native recipe "+id);p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);world.getBlockState(pos).useWithoutItem(world,p,new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false));require(world.getBlockState(pos).isAir(),"Cloth ritual converted to scroll "+id);var item=world.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(pos).inflate(1),e->e.getItem().is(ModItems.REGISTERED.get("scroll_"+id))).stream().findFirst().orElseThrow();require(Utils.getScrollMahou(item.getItem()).getCasterUUID().orElseThrow().equals(p.getUUID()),"Original scroll binding "+id);item.discard();p.getInventory().clearContent();}
